"""Future eligibility gate only. No real dataset generated by preparation."""
from .runner import read,HERE,CAMPAIGN_ID,verify_frozen,ContractError
from stage4e_d0.handoff import read_qualified_run as original_read,verify_artifacts,known_path_annotations

def read_qualified_run(campaign,run_config):
    verify_artifacts(campaign)
    result=read(campaign/'CAMPAIGN_COMPLETED.json')
    if (result.get('campaign_id')!=CAMPAIGN_ID or result.get('classification')!='PASS_QUALIFICATION'
        or result.get('binding',{}).get('proposal_sha256')!=verify_frozen()):
        raise ContractError('Only new complete frozen qualification evidence may be considered')
    directory=campaign/run_config['attempt_id'];completion=read(directory/'RUN_COMPLETED.json')
    if completion.get('unresolved_events')!=0:raise ContractError('Unresolved events remain quarantined')
    records=[__import__('json').loads(line) for line in (directory/'steps.jsonl').read_text().splitlines()]
    resolutions=read(directory/'event_resolutions.json')
    pending=[r for r in records if r['setpoint_validation_at_receipt']['status']=='PENDING_EVENT_VERIFICATION']
    if len(resolutions)!=len(pending):raise ContractError('Missing or surplus event resolution')
    for record in pending:
        matches=[r for r in resolutions if r['event_time']==record['end']]
        if len(matches)!=1:raise ContractError('Pending event lacks unique resolution')
        resolution=matches[0]
        if (resolution['status']!='RESOLVED_EVENT_VERIFICATION' or resolution['resolved_at_sim']!=record['end']+300
            or resolution['endpoint_at_event']!=read(directory/f"endpoint_{(record['end']-run_config['start'])//300:04d}.json")):
            raise ContractError('Invalid event validation provenance')
    # Original builder uses unchanged actual endpoints, histories, issued forecasts,
    # origin cutoffs and known paths. Resolutions are never copied into features.
    return original_read(campaign,run_config)
